# Blocks reviewed by reading samples of every one: only these keep their actions and settings sensible together
KEEP = {0,1,3,4,7,8,9,11,12,13,16,18,19,21,28,29,33,34,35,40,41}
def build():
    out=[]
    for i,(acts,ctxs) in enumerate(BLOCKS):
        if i not in KEEP: continue
        for a in acts:
            for c in ctxs:
                out.append(f"Quem é mais provável de {a} {c}?")
    return out
if __name__=='__main__':
    import json
    q=build(); print(len(q)); print(*q[:6],sep='\n')
